fn solve(w: i8, a: i8, b: i8) -> i8 {
    // Compute the absolute difference between the starting points
    let dist = (a - b).abs();

    // If the intervals already touch or overlap, no shift is needed
    if dist <= w {
        0
    } else {
        // Otherwise, the shift is the gap between them minus the width
        dist - w
    }
}

fn main() {
    // Example usage:
    // Interval width = 3, starting positions = 1 and 7.
    // The distance between starts is 6, so the required shift is 6 - 3 = 3.
    let w = 3;
    let a = 1;
    let b = 7;
    let result = solve(w, a, b);
    println!("{}", result); // prints "3"
}